/// Example 1 of `insufficient`.
#[test]
fn insufficient_example_1() {
    let wanted: types::Need = types::Need::ByField {
        object: types::ObjectTypeId("note".to_string()),
        field: types::FieldId("slug".to_string()),
        value: types::Value::Str("first".to_string()),
    };
    let want_: types::DomainError = types::DomainError {
        kind: types::ErrorKind::InsufficientState,
        message: "the snapshot does not cover ByField { object: ObjectTypeId(\"note\"), field: FieldId(\"slug\"), value: Str(\"first\") }"
            .to_string(),
        evidence: vec![
            types::Check { rule : "coverage".to_string(), passed : false, detail :
            "ByField { object: ObjectTypeId(\"note\"), field: FieldId(\"slug\"), value: Str(\"first\") }"
            .to_string() }
        ],
        missing: Some(types::Need::ByField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("slug".to_string()),
            value: types::Value::Str("first".to_string()),
        }),
    };
    assert_eq!(insufficient(&wanted), want_);
}

