/// A schema with a problem of each kind the kernel states, in its order: the limit of a query, a read condition, the permissions of roles, a team, an invitation, a policy (WG-5095, WG-5077).
#[test]
fn schema_problems_example_3() {
    let schema: types::TenantSchema = {
        let mut fixture = fixture_fx_tenant_schema_5();
        fixture.invitations = Some(std::collections::BTreeMap::from([(
            types::InvitationId("welcome".to_string()),
            types::InvitationDef {
                id: types::InvitationId("welcome".to_string()),
                address: "".to_string(),
                roles: std::collections::BTreeSet::new(),
                created_by: types::PrincipalId("alpha:owner".to_string()),
                redeemed_by: None,
                expires_at: None,
                revoked_by: None,
            },
        )]));
        fixture
            .objects
            .get_mut(&types::ObjectTypeId("note".to_string()))
            .expect("the fixture has the key")
            .fields
            .get_mut(&types::FieldId("title".to_string()))
            .expect("the fixture has the key")
            .read = Some(types::Expr::Len(Box::new(types::Expr::Var(
            types::Scope::Record,
            "title".to_string(),
        ))));
        fixture.policies.insert(
            types::PolicyId("boss".to_string()),
            types::PolicyDef {
                id: types::PolicyId("boss".to_string()),
                role: types::RoleId("owner".to_string()),
                resource: types::Resource::Schema,
                actions: std::collections::BTreeSet::from([types::Action::Manage]),
                condition: None,
            },
        );
        fixture.queries.insert(
            types::QueryId("zero".to_string()),
            types::QueryDef {
                id: types::QueryId("zero".to_string()),
                object: types::ObjectTypeId("note".to_string()),
                filter: None,
                params: std::collections::BTreeSet::new(),
                order: Vec::new(),
                limit: Some(0),
                aggregates: None,
                declared_fields: None,
            },
        );
        fixture.role_permissions = Some(std::collections::BTreeMap::from([
            (
                types::RoleId("ghost".to_string()),
                vec![types::Permission::Capability("x".to_string())],
            ),
            (
                types::RoleId("owner".to_string()),
                vec![types::Permission::Capability(" ".to_string())],
            ),
        ]));
        fixture.teams = Some(std::collections::BTreeMap::from([(
            types::TeamId("desk".to_string()),
            types::TeamDef {
                id: types::TeamId("desk".to_string()),
                label: "Desk".to_string(),
                members: std::collections::BTreeSet::new(),
                roles: std::collections::BTreeSet::from([types::RoleId("public".to_string())]),
            },
        )]));
        fixture
    };
    let want_: Vec<String> = vec![
        "limit: query zero declares a limit outside 1 to 200".to_string(),
        "note.title: read is Int, not a truth value".to_string(),
        "role ghost: permissions of an unknown role".to_string(),
        "role owner: the owner role holds every permission".to_string(),
        "role owner: a capability needs a name".to_string(),
        "team desk: everyone already holds public".to_string(),
        "invitation welcome: names no address".to_string(),
        "policy boss: the owner role needs no policy".to_string(),
    ];
    assert_eq!(schema_problems(&schema), Ok(want_));
}

