/// bundle.rs: a seeded post with a symbolic author, tags and a date.
#[test]
fn coerce_fields_example_1() {
    let object: types::ObjectTypeDef = fixture_fx_object_type_def_3();
    let fields: std::collections::BTreeMap<String, types::PlainJson> =
        std::collections::BTreeMap::from([
            (
                "author".to_string(),
                types::PlainJson::String("@ines".to_string()),
            ),
            (
                "published_at".to_string(),
                types::PlainJson::String("2026-11-18T09:30Z".to_string()),
            ),
            (
                "tags".to_string(),
                types::PlainJson::Array(vec![types::PlainJson::String("clay".to_string())]),
            ),
            (
                "title".to_string(),
                types::PlainJson::String("Kiln".to_string()),
            ),
        ]);
    let refs: std::collections::BTreeMap<String, types::RecordId> =
        std::collections::BTreeMap::from([("@ines".to_string(), types::RecordId(2))]);
    let times: std::collections::BTreeMap<String, i64> =
        std::collections::BTreeMap::from([("2026-11-18T09:30Z".to_string(), 1794994200000)]);
    let want_: std::collections::BTreeMap<types::FieldId, types::Value> =
        std::collections::BTreeMap::from([
            (
                types::FieldId("author".to_string()),
                types::Value::Ref(types::RecordId(2)),
            ),
            (
                types::FieldId("published_at".to_string()),
                types::Value::Time(1794994200000),
            ),
            (
                types::FieldId("tags".to_string()),
                types::Value::List(vec![types::Value::Str("clay".to_string())]),
            ),
            (
                types::FieldId("title".to_string()),
                types::Value::Str("Kiln".to_string()),
            ),
        ]);
    assert_eq!(coerce_fields(&object, &fields, &refs, &times), Ok(want_));
}

