/// Example 1 of `refuse`.
#[test]
fn refuse_example_1() {
    let kind: types::ErrorKind = types::ErrorKind::TenantNotFound;
    let rule: String = "tenant:exists".to_string();
    let message: String = "no such tenant".to_string();
    let want_: types::DomainError = types::DomainError {
        kind: types::ErrorKind::TenantNotFound,
        message: "no such tenant".to_string(),
        evidence: vec![types::Check {
            rule: "tenant:exists".to_string(),
            passed: false,
            detail: "no such tenant".to_string(),
        }],
        missing: None,
    };
    assert_eq!(refuse(&kind, &rule, &message), want_);
}

