/// Example 1 of `policy-check-text`.
#[test]
fn policy_check_text_example_1() {
    let c: types::PolicyCheck = types::PolicyCheck {
        rule: "policy:writers_edit_own".to_string(),
        passed: true,
        what: "Update on Object(ObjectTypeId(\"note\"))".to_string(),
        outcome: types::PolicyOutcome::Held,
        condition: Some(types::Expr::Cmp(
            types::CmpOp::Eq,
            Box::new(types::Expr::Var(
                types::Scope::Record,
                "$created_by".to_string(),
            )),
            Box::new(types::Expr::Principal),
        )),
    };
    let want_: types::Check = types::Check {
        rule: "policy:writers_edit_own".to_string(),
        passed: true,
        detail: "Update on Object(ObjectTypeId(\"note\")) where (record.$created_by == principal)"
            .to_string(),
    };
    assert_eq!(policy_check_text(&c), want_);
}

/// Example 2 of `policy-check-text`.
#[test]
fn policy_check_text_example_2() {
    let c: types::PolicyCheck = types::PolicyCheck {
        rule: "policy:writers_edit_own".to_string(),
        passed: false,
        what: "Update on Object(ObjectTypeId(\"note\"))".to_string(),
        outcome: types::PolicyOutcome::IsFalse,
        condition: Some(types::Expr::Cmp(
            types::CmpOp::Eq,
            Box::new(types::Expr::Var(
                types::Scope::Record,
                "$created_by".to_string(),
            )),
            Box::new(types::Expr::Principal),
        )),
    };
    let want_: types::Check = types::Check {
        rule: "policy:writers_edit_own".to_string(),
        passed: false,
        detail: "(record.$created_by == principal) is false".to_string(),
    };
    assert_eq!(policy_check_text(&c), want_);
}

