/// A condition that could not be evaluated reads as an evaluation failure.
#[test]
fn policy_check_text_example_6() {
    let c: types::PolicyCheck = types::PolicyCheck {
        rule: "policy:writers_edit_own".to_string(),
        passed: false,
        what: "Update on Object(ObjectTypeId(\"note\"))".to_string(),
        outcome: types::PolicyOutcome::Failed,
        condition: Some(types::Expr::Cmp(
            types::CmpOp::Eq,
            Box::new(types::Expr::Var(
                types::Scope::Record,
                "$created_by".to_string(),
            )),
            Box::new(types::Expr::Principal),
        )),
    };
    let want_: types::Check = types::Check {
        rule: "policy:writers_edit_own".to_string(),
        passed: false,
        detail: "(record.$created_by == principal): evaluation failed".to_string(),
    };
    assert_eq!(policy_check_text(&c), want_);
}
